css:
@import url("https://fonts.googleapis.com/css2?family=Yeseva+One&family=Work+Sans:wght@400;500;600&display=swap");
:root{--ink:#1E2240;--cb:#5B7FDB;--cb2:#4466C2;--pb:#EEF1FB;--yl:#FFD166;--gr:#555A75;--ln:#DADFF0;--h:"Yeseva One",Georgia,serif;--b:"Work Sans",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:18px;line-height:1.65;color:var(--ink);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:400;margin:0;line-height:1.1}
.wrap{max-width:1140px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--yl);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--yl);outline-offset:2px}
.nav{display:flex;justify-content:space-between;align-items:center;height:76px;position:relative}.logo{font-family:var(--h);font-size:22px;text-decoration:none}.menu{display:flex;gap:24px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none}.burger{display:none;background:none;border:2px solid var(--ink);width:44px;height:40px;border-radius:10px;font-size:20px;cursor:pointer}
.hero{background:var(--pb);padding:50px 0 80px}.hg{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:center}.hg>*{min-width:0}
.hero h1{font-size:clamp(40px,5.2vw,68px)}.hero p{font-size:20px;color:var(--gr);margin:18px 0 22px}
.chk{list-style:none;padding:0;margin:0 0 26px}.chk li{padding:6px 0 6px 34px;position:relative}.chk li:before{content:"✓";position:absolute;left:0;top:6px;width:24px;height:24px;border-radius:50%;background:var(--cb);color:#fff;font-size:14px;display:grid;place-items:center}
.book{perspective:1200px;display:flex;justify-content:center}.cover{width:min(330px,80vw);aspect-ratio:3/4.2;background:var(--cb);border-radius:6px 16px 16px 6px;box-shadow:inset 14px 0 0 rgba(0,0,0,.15),24px 30px 50px rgba(30,34,64,.3);transform:rotateY(-14deg);padding:34px 28px;color:#fff;display:flex;flex-direction:column;position:relative;overflow:hidden}
.cover small{font-weight:600;letter-spacing:.06em}.cover b{font-family:var(--h);font-weight:400;font-size:42px;line-height:1.05;margin-top:18px}.cover span{margin-top:auto;font-size:15px}.cover svg{position:absolute;right:-30px;top:120px;width:220px;opacity:.9}
.form{background:#fff;border-radius:22px;padding:24px;box-shadow:0 20px 40px rgba(30,34,64,.1)}.form label{display:block;font-weight:500;font-size:15px;margin-bottom:6px}.form input,.form select{width:100%;font:17px var(--b);padding:12px;border:2px solid var(--ln);border-radius:12px;margin-bottom:12px;color:var(--ink)}
.btn{display:inline-block;background:var(--ink);color:#fff;text-decoration:none;font:600 17px var(--b);padding:14px 24px;border-radius:40px;border:0;cursor:pointer}.form .btn{width:100%}.btn.y{background:var(--yl);color:var(--ink)}
.fine{font-size:14px;color:var(--gr);margin:10px 0 0}.ok{background:var(--pb);border-radius:16px;padding:16px;margin-top:12px}.ok p{margin:0 0 10px}
section{padding:80px 0}.sh{max-width:640px;margin-bottom:28px}.sh h2{font-size:clamp(34px,4.4vw,52px)}.sh p{color:var(--gr);margin:10px 0 0}
.tabs{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px}.tabs button{font:600 15px var(--b);background:var(--pb);border:0;border-radius:30px;padding:9px 16px;cursor:pointer;color:var(--ink)}.tabs button[aria-pressed=true]{background:var(--ink);color:#fff}
.page{background:#fffdf7;border:1px solid var(--ln);border-radius:8px;padding:34px 40px;max-width:760px;box-shadow:8px 8px 0 var(--pb)}.page h3{font-size:30px}.page .n{color:var(--cb2);font-weight:600;font-size:15px}.page p{color:#3E435E}
.page .fade{position:relative;max-height:150px;overflow:hidden}.page .fade:after{content:"";position:absolute;left:0;right:0;bottom:0;height:70px;background:linear-gradient(transparent,#fffdf7)}
.stats{background:var(--ink);color:#fff}.stats .wrap{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;padding-top:34px;padding-bottom:34px}.stats b{display:block;font-family:var(--h);font-size:44px;color:var(--yl);font-weight:400}.stats span{color:#C6CAE0}
.q{max-width:760px}.q blockquote{margin:0;font-family:var(--h);font-size:28px;line-height:1.35}.q cite{display:block;margin-top:12px;font-style:normal;color:var(--gr);font-family:var(--b);font-size:16px}
footer{padding:26px 0;font-size:15px;color:var(--gr);border-top:1px solid var(--ln)}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:900px){.hg{grid-template-columns:1fr}.stats .wrap{grid-template-columns:1fr}.page{padding:24px}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:76px;left:0;right:0;background:#fff;flex-direction:column;padding:18px 22px;z-index:30}.menu.open{display:flex}.cover{transform:none}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);
const C=[["Chapter 1","Why email feels endless","Most of us check email around 15 times an hour. Every check pulls us out of real work, and it takes about 20 minutes to get properly focused again. The problem isn't the number of emails. It's that the inbox has become a to-do list that anyone in the world can add to. In this chapter we'll take that power back, one small habit at a time."],["Chapter 2","The 3-folder system","Forget colour-coded labels. You need three folders: Reply, Waiting and Done. Anything that takes less than two minutes, answer straight away. Anything longer goes into Reply. Anything you're waiting on goes into Waiting. Everything else goes into Done. By the end of this chapter your inbox will be empty, and it will feel strange."],["Chapter 3","Saying no, kindly","A short, polite no is kinder than a slow, vague maybe. Here's a reply you can use today: 'Thanks so much for thinking of me. I can't take this on right now, but I hope it goes brilliantly.' We'll look at 6 more versions for work, family and friends."],["Chapter 4","The 20-minute routine","Twice a day, at times you choose, open email with a timer running. Process top to bottom, using the three folders. When the timer ends, close the tab. At first this feels risky. After a week it feels like freedom."]];
let ci=0;function ch(){$('tabs').innerHTML=C.map((c,i)=>`<button type="button" aria-pressed="${i===ci}" data-i="${i}">${c[1]}</button>`).join('');$('cn').textContent=C[ci][0];$('ch').textContent=C[ci][1];$('cp').textContent=C[ci][2]}
$('tabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;ci=+b.dataset.i;ch()};ch();
$('df').onsubmit=e=>{e.preventDefault();$('okt').textContent=`Thanks ${$('dn').value}! We've emailed the full guide to ${$('de').value}. You can also download a sample now.`;$('dl').href='data:text/plain;charset=utf-8,'+encodeURIComponent('The Calm Inbox (sample)\n\n'+C.map(c=>c[0]+': '+c[1]+'\n'+c[2]).join('\n\n'));$('ok').hidden=false};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
